def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def countUnivalueSubtrees(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    ok = [True] * n
    count = 0
    for k in range(n - 1, -1, -1):
        for c in (left[k], right[k]):
            if c != -1 and not (ok[c] and vals[c] == vals[k]):
                ok[k] = False
        if ok[k]:
            count += 1
    return count
